using namespace std;

struct Bar {
    double open;
    double close;
    double volume;
};
using History = map<string, vector<Bar>>;
using Weights = map<string, double>;

vector<double> closes(const vector<Bar>& bars) {
    vector<double> out;
    for (const Bar& b : bars) out.push_back(b.close);
    return out;
}
vector<double> volumes(const vector<Bar>& bars) {
    vector<double> out;
    for (const Bar& b : bars) out.push_back(b.volume);
    return out;
}
vector<double> returns(const vector<double>& c) {
    vector<double> out;
    for (int i = 1; i < int(c.size()); i++) out.push_back(c[i] / c[i - 1] - 1);
    return out;
}
vector<double> tail(const vector<double>& x, int n) {
    return vector<double>(x.end() - n, x.end());
}
double avg(const vector<double>& x) {
    double sum = 0;
    for (double z : x) sum += z;
    return sum / x.size();
}
double var(const vector<double>& x) {
    double mean = avg(x), sum = 0;
    for (double z : x) sum += (z - mean) * (z - mean);
    return sum / x.size();
}
double ema(const vector<double>& x, int period) {
    double a = 2.0 / (period + 1);
    double result = x[0];
    for (int i = 1; i < int(x.size()); i++)
        result = a * x[i] + (1 - a) * result;
    return result;
}

Weights signals(const History& history) {
    vector<pair<double,string>> ranked;
    map<string,double> values;
    for (const auto& item : history) {
        const string& name = item.first;
        const vector<Bar>& bars = item.second;
        if (bars.size() < 61) continue;
        vector<double> c = closes(bars);
        vector<double> v = volumes(bars);
        vector<double> r = returns(c);
        auto x=tail(c,40);
double low=*min_element(x.begin(),x.end()),high=*max_element(x.begin(),x.end());
double z=high-low>1e-12?(c.back()-low)/(high-low):0.5;
double score=0.5-z;
        if (!isfinite(score) || fabs(score) >= 1e6) continue;
        values[name] = score;
        if (fabs(score) > 1e-12) ranked.push_back({fabs(score),name});
    }
    sort(ranked.begin(), ranked.end());
    Weights result;

    if (!ranked.empty()) {
        string name = ranked.back().second;
        result[name] = values[name] > 0 ? 1.0 : -1.0;
    }
    return result;
}

int main() {
    int n;
    if (!(cin >> n) || n < 0) return 0;
    History history;
    for (int i = 0; i < n; i++) {
        string name;
        int count;
        cin >> name >> count;
        if (count < 0) return 1;
        vector<Bar> bars(count);
        for (int j = 0; j < count; j++) {
            cin >> bars[j].open >> bars[j].close >> bars[j].volume;
            if (!cin || bars[j].open <= 0 || bars[j].close <= 0 || bars[j].volume < 0) return 1;
        }
        history[name] = bars;
    }
    Weights weights = signals(history);
    cout << fixed << setprecision(10);
    for (const auto& item : weights) cout << item.first << " " << item.second << "\n";
    return 0;
}

